sys_script.script:
(function executeRule(current, previous) {

    var POINTS_PER_PRIOR_REPORT = 15;
    var POINTS_CONFIRMED_HISTORY = 40;
    var SCORE_CAP = 100;
    var FLAG_THRESHOLD = 70;

    var assetPassportId = current.getValue('asset_passport');
    if (!assetPassportId) {
        // No linked asset passport — can't score
        current.setValue('risk_score', 0);
        return;
    }

    // Factor 1: Count prior fraud reports against the same asset_passport
    // (exclude the current record to avoid self-counting)
    var priorCount = 0;
    var gr = new GlideRecord('x_1919710_refurt_0_fraud_report');
    gr.addQuery('asset_passport', assetPassportId);
    gr.addQuery('sys_id', '!=', current.getUniqueValue());
    gr.query();
    priorCount = gr.getRowCount();

    // Factor 2: Check if any prior report has status = 'confirmed'
    var hasConfirmedPrior = false;
    var grConfirmed = new GlideRecord('x_1919710_refurt_0_fraud_report');
    grConfirmed.addQuery('asset_passport', assetPassportId);
    grConfirmed.addQuery('sys_id', '!=', current.getUniqueValue());
    grConfirmed.addQuery('status', 'confirmed');
    grConfirmed.setLimit(1);
    grConfirmed.query();
    hasConfirmedPrior = grConfirmed.hasNext();

    // Calculate score: (prior_count * 15) + (has_confirmed * 40), capped at 100
    var score = (priorCount * POINTS_PER_PRIOR_REPORT) +
                (hasConfirmedPrior ? POINTS_CONFIRMED_HISTORY : 0);
    if (score > SCORE_CAP) {
        score = SCORE_CAP;
    }

    // Store risk_score on the fraud_report record (per-report history)
    current.setValue('risk_score', score);

    // Update risk_score on the linked asset_passport (latest score for quick lookup)
    var apGr = new GlideRecord('x_1919710_refurt_0_asset_passport');
    if (apGr.get(assetPassportId)) {
        apGr.setValue('risk_score', score);

        // If score crosses the threshold, flag the asset_passport
        if (score >= FLAG_THRESHOLD) {
            apGr.setValue('passport_status', 'flagged');
        }

        apGr.update();
    }

})(current, previous);
